import 'package:drift/native.dart'; import 'package:flutter_test/flutter_test.dart'; import 'package:organization_task_manager/core/domain/app_clock.dart'; import 'package:organization_task_manager/core/domain/entities.dart'; import 'package:organization_task_manager/core/storage/database/app_database.dart'; import 'package:organization_task_manager/core/storage/database/daos/task_dao.dart'; import 'package:organization_task_manager/core/storage/database/daos/user_dao.dart'; import 'package:organization_task_manager/core/storage/database/daos/organization_dao.dart'; import 'package:organization_task_manager/core/storage/database/seed/demo_data_service.dart'; import 'package:organization_task_manager/core/storage/repositories/local_task_repository.dart'; import 'package:organization_task_manager/core/storage/repositories/local_user_repository.dart'; import 'package:organization_task_manager/core/storage/repositories/local_organization_repository.dart';
void main(){late AppDatabase db;final clock=FixedAppClock(DateTime.utc(2026,1,15));setUp(() async {db=AppDatabase.forTesting(NativeDatabase.memory());await DemoDataService(db,clock).ensureSeeded();});tearDown(() async=>db.close());test('user repository returns domain users across organizational queries',() async {final r=LocalUserRepository(UserDao(db));expect(await r.getUserById('user-ahmed-hassan'),isA<OrganizationUser>());expect(await r.getActiveUsers(),isNotEmpty);expect(await r.getUsersByDepartment('department-operations'),isNotEmpty);expect(await r.getDirectReports('user-sara-mahmoud'),isNotEmpty);expect(await r.getUsersByTeam('team-field-operations'),isNotEmpty);});test('organization and task repositories return domain entities',() async {final o=LocalOrganizationRepository(OrganizationDao(db));expect((await o.getDepartments()).first,isA<Department>());expect(await o.getTeamsByDepartment('department-operations'),hasLength(2));final r=LocalTaskRepository(TaskDao(db));expect(await r.getTaskByNumber('SCN-01'),isA<Task>());expect(await r.getTasksForUser('user-ahmed-hassan'),isNotEmpty);expect(await r.getTasksForTeam('team-technical-support-queue'),hasLength(2));expect(await r.getTasksByBatch('batch-policy-annual'),hasLength(12));expect(await r.getChecklistItems('scenario-01'),hasLength(2));expect(await r.getBlockers('scenario-04'),hasLength(1));expect(await r.getExtensionRequests('scenario-09'),hasLength(1));});}
